import { Project } from '../../src'
import { GUID, type File } from '@servicenow/sdk-build-core'

describe('Workspace plugin test suite', () => {
    describe('Fluent to XML', () => {
        const project = new Project({
            config: {
                scope: 'x_snc_test',
                scopeId: 'aaaa1111bbbb2222cccc3333dddd4444',
            },
            packageJson: {
                name: 'x_snc_test',
                version: '1.0.0',
            },
        })

        afterAll(() => {
            project?.dispose()
        })

        afterEach(() => {
            project
                .getFiles()
                .filter((f) => f.getPath().endsWith('now.ts') || f.getPath().endsWith('.js'))
                .forEach((file) => {
                    project.removeFile(file)
                })
        })

        test('create workspace from fluent', async () => {
            const workspaceId = GUID()
            const listConfigId = GUID()
            const title = 'Test Workspace'
            const path = 'test_workspace'
            const landingPath = 'test_home'
            const active = 'false'
            const tables = ['incident', 'problem', 'sys_user']

            const file = project.addFile({
                path: 'workspace.now.ts',
                content: `import { Workspace } from '@servicenow/sdk/core'
Workspace({
    $id: Now.ID['${workspaceId}'],
    title: '${title}',
    path: '${path}',
    landingPath: '${landingPath}',
    active: ${active},
    tables: [${tables.map((table) => `'${table}'`).join(', ')}],
    listConfig: '${listConfigId}',
})
`,
            })

            const diagnostics = (await project.getDiagnostics()).map((d) => d.message)
            expect(diagnostics).toHaveLength(0)
            const allXmls = await file.getOutput()
            expect(allXmls).toHaveLength(23) // pagereg + appconfig + 4-screentypes, 4-screens, 4-approutes, 7-page-props, 1-registry-m2m-category, 1-macroponent

            expectWorkspace({ allXmls, workspaceId, active, path, title, landingPath, tables, listConfigId })
        })

        test('create workspace from fluent - using defaults', async () => {
            const workspaceId = GUID()
            const listConfigId = 'd305c0a873601010a0a79329faf6a7cb' // DEFAULT
            const title = 'Test Workspace'
            const path = 'test_workspace'
            const landingPath = 'home' // DEFAULT
            const active = 'true' // DEFAULT
            const tables = ['sys_ux_macroponent']

            const file = project.addFile({
                path: 'workspace.now.ts',
                content: `import { Workspace } from '@servicenow/sdk/core'
Workspace({
    $id: Now.ID['${workspaceId}'],
    title: '${title}',
    path: '${path}',
    tables: [${tables.map((table) => `'${table}'`).join(', ')}],
})
`,
            })

            const diagnostics = (await project.getDiagnostics()).map((d) => d.message)
            expect(diagnostics).toHaveLength(0)
            const allXmls = await file.getOutput()
            expect(allXmls).toHaveLength(23) // pagereg + appconfig + 4-screentypes, 4-screens, 4-approutes, 7-page-props, 1-registry-m2m-category, 1-macroponent

            expectWorkspace({ allXmls, workspaceId, active, path, title, landingPath, tables, listConfigId })
        })
    })
})

const expectWorkspace = ({
    allXmls,
    workspaceId,
    active,
    path,
    landingPath,
    title,
    tables,
    listConfigId,
}: {
    allXmls: File[]
    workspaceId: string
    active: string
    path: string
    landingPath: string
    title: string
    tables: string[]
    listConfigId: string
}) => {
    const pageRegXml = allXmls.filter((x) => x.path.includes(`sys_ux_page_registry_`))
    expect(pageRegXml).toHaveLength(1)
    expectPageReg(pageRegXml[0], workspaceId, active, path, title)
    const xml = pageRegXml[0].content
    const match = xml.match(/<admin_panel>([^<]+)<\/admin_panel>/)
    const appConfigId = match?.[1]

    const appConfigXml = allXmls.filter((x) => x.path.includes(`sys_ux_app_config_`))
    expect(appConfigXml).toHaveLength(1)
    expectAppConfig(appConfigXml[0], appConfigId, landingPath, title)

    const pagePropXmls = allXmls.filter((x) => x.path.includes(`sys_ux_page_property_`))
    expect(pagePropXmls).toHaveLength(7)

    const listConfigPageProp = pagePropXmls.find((x) => x.content.includes(`<name>listConfigId</name>`))
    expect(listConfigPageProp).toBeDefined()
    expect(listConfigPageProp?.content).toContain(`<value>${listConfigId}</value>`)

    const chromeTabPageProp = pagePropXmls.find((x) => x.content.includes(`<name>chrome_tab</name>`))
    expect(chromeTabPageProp).toBeDefined()
    tables.forEach((table) => expect(chromeTabPageProp.content).toContain(`"${table}"`))
    expect(chromeTabPageProp.content.split(`"routeInfo"`).length - 1).toBe(tables.length)

    const expectedLength = 4 // Expected amount multiple types since there are 4 pages in the workspace
    const appRouteXmls = allXmls.filter((x) => x.path.includes(`sys_ux_app_route_`))
    expect(appRouteXmls).toHaveLength(expectedLength)
    const screenTypeXmls = allXmls.filter((x) => x.path.includes('sys_ux_screen_type_'))
    expect(screenTypeXmls).toHaveLength(expectedLength)
    const screenXmls = allXmls.filter(
        (x) => x.path.includes('sys_ux_screen_') && !x.path.includes('sys_ux_screen_type_')
    )
    expect(screenXmls).toHaveLength(expectedLength)

    for (let i = 0; i < expectedLength; i++) {
        const match = appRouteXmls[i].content.match(/<route_type>([^<]+)<\/route_type>/)
        const routeType = match?.[1]

        switch (routeType) {
            case 'home':
                expectUxfPage(
                    appRouteXmls[i],
                    allXmls,
                    appConfigId,
                    'home',
                    '',
                    'sysId,edit,tabSysId,filter,element',
                    'Dashboards Default'
                )
                break
            case 'list':
                expectUxfPage(appRouteXmls[i], allXmls, appConfigId, 'list', '', 'listId', 'List Page')
                break
            case 'record':
                expectUxfPage(
                    appRouteXmls[i],
                    allXmls,
                    appConfigId,
                    'record',
                    'table,sysId',
                    'query,extraParams,views,selectedTab',
                    'Record Default'
                )
                break
            case 'simplelist':
                expectUxfPage(
                    appRouteXmls[i],
                    allXmls,
                    appConfigId,
                    'simplelist',
                    'table',
                    'listTitle,query,disableInlineEditing',
                    'Simple List'
                )
                break
            default:
                // do the opposite of expect(), force this to fail
                throw new Error(`Unexpected route type: ${routeType}`)
        }
    }
}

const expectPageReg = (
    xml: File,
    workspaceId: string,
    workspaceActive: string,
    workspacePath: string,
    workspaceName: string
) => {
    const content = xml.content

    expect(content).toContain('<sys_ux_page_registry action')
    expect(content).toContain(`<sys_id>${workspaceId}</sys_id>`)
    expect(content).toContain(`<active>${workspaceActive}</active>`)
    expect(content).toContain('<admin_panel_table>sys_ux_app_config</admin_panel_table>')
    expect(content).toContain('<parent_app>c86a62e2c7022010099a308dc7c26022</parent_app>')
    expect(content).toContain(`<path>${workspacePath}</path>`)
    expect(content).toContain('<root_macroponent>c276387cc331101080d6d3658940ddd2</root_macroponent>')
    expect(content).toContain(`<title>${workspaceName}</title>`)
}

const expectAppConfig = (xml: File, appConfigId: string, landingPath: string, name: string) => {
    const content = xml.content
    expect(content).toContain('<sys_ux_app_config action')
    expect(content).toContain(`<sys_id>${appConfigId}</sys_id>`)
    expect(content).toContain(`<active>true</active>`)
    expect(content).toContain('<custom_icon/>')
    expect(content).toContain('<description>Workspace created by Fluent</description>')
    expect(content).toContain('<disable_auto_reflow>false</disable_auto_reflow>')
    expect(content).toContain('<encode_query_string>false</encode_query_string>')
    expect(content).toContain('<icon/>')
    expect(content).toContain(`<landing_path>${landingPath}</landing_path>`)
    expect(content).toContain(`<name>${name}</name>`)
}

const expectUxfPage = (
    appRouteXml: File,
    allXmls: File[],
    appConfigId: string,
    routeType: string,
    fields: string,
    optionalParameters: string,
    name: string
) => {
    expectAppRoute(appRouteXml, appConfigId, routeType, fields, optionalParameters, name)

    const match = appRouteXml.content.match(/<screen_type>([^<]+)<\/screen_type>/)
    const screenTypeId = match?.[1]
    const screenTypeXmls = allXmls.filter((xml) => xml.path.includes(screenTypeId))
    expect(screenTypeXmls.length).toBe(1)
    expectScreenType(screenTypeXmls[0], name)

    const screenXmls = allXmls
        .filter((xml) => xml.path.includes('sys_ux_screen_'))
        .filter((xml) => xml.content.includes(`<screen_type>${screenTypeId}</screen_type>`))
    expect(screenXmls.length).toBe(1)

    expectScreen(screenXmls[0], name, appConfigId, screenTypeId)
}

const expectAppRoute = (
    xml: File,
    appConfigId: string,
    routeType: string,
    fields: string,
    optionalParameters: string,
    name: string
) => {
    const content = xml.content
    expect(content).toContain('<sys_ux_app_route action')
    expect(content).toContain(`<app_config>${appConfigId}</app_config>`)
    expect(content).toContain('<description/>')
    expect(content).toContain('<extension_point/>')
    expect(content).toContain(fields ? `<fields>${fields}</fields>` : '<fields/>')
    expect(content).toContain('<icon/>')
    expect(content).toContain('<interoperable>false</interoperable>')
    expect(content).toContain(`<name>${name}</name>`)
    expect(content).toContain(
        optionalParameters
            ? `<optional_parameters>${optionalParameters}</optional_parameters>`
            : '<optional_parameters/>'
    )
    expect(content).toContain('<order>0</order>')
    expect(content).toContain('<parent_macroponent>c276387cc331101080d6d3658940ddd2</parent_macroponent>')
    expect(content).toContain('<parent_macroponent_composition_element_id/>')
    expect(content).toContain(`<route_type>${routeType}</route_type>`)
}

const expectScreenType = (xml: File, name: string) => {
    const content = xml.content
    expect(content).toContain('<sys_ux_screen_type action')
    expect(content).toContain(`<name>${name}</name>`)
    expect(content).toContain('<description/>')
}

const expectScreen = (xml: File, name: string, appConfigId: string, screenTypeId: string) => {
    const content = xml.content
    expect(content).toContain('<sys_ux_screen action')
    expect(content).toContain(`<name>${name}</name>`)
    expect(content).toContain('<description/>')
    expect(content).toContain('<active>true</active>')
    expect(content).toContain(`<app_config>${appConfigId}</app_config>`)
    expect(content).toContain('<description/>')
    expect(content).toContain('<disable_auto_reflow>false</disable_auto_reflow>')
    expect(content).toContain('<disable_interoperable>false</disable_interoperable>')
    expect(content).toContain('<event_mappings/>')
    expect(content).toContain('<order>0</order>')
    expect(content).toContain('<parent_macroponent>c276387cc331101080d6d3658940ddd2</parent_macroponent>')
    expect(content).toContain('<required_translations/>')
    expect(content).toContain('<rollback_screen/>')
    expect(content).toContain('<screen_condition/>')
    expect(content).toContain(`<screen_type>${screenTypeId}</screen_type>`)
}
